-- Plan highlights after the roadmap modules shipped (stage 2). Rows edited by a Super Admin are left alone.
UPDATE plans SET highlights = '["Up to 50 employees", "2 branches", "Nepal payroll (tax, SSF, PF, CIT)", "Biometric devices and shifts", "Recruitment and onboarding", "Expense claims and request forms", "PDF/Excel export & document alerts"]'::jsonb WHERE code = 'PROFESSIONAL' AND highlights = '["Up to 50 employees", "2 branches", "Nepal payroll (tax, SSF, PF, CIT)", "Biometric devices", "Shift schedules", "PDF/Excel export & document alerts"]'::jsonb;
UPDATE plans SET highlights = '["Up to 150 employees", "5 branches", "Everything in Professional", "Performance reviews and training", "Assets and HR helpdesk", "Surveys and workforce planning", "50 GB document storage"]'::jsonb WHERE code = 'BUSINESS' AND highlights = '["Up to 150 employees", "5 branches", "50 GB document storage", "Everything in Professional", "Upcoming modules included as they launch"]'::jsonb;
